(()=>{'use strict';if(window.__gcUltimateMobileUx)return;window.__gcUltimateMobileUx=true;const mobile=()=>window.matchMedia('(max-width:760px)').matches;const primary=[['overview','⌂','داشبۆرد'],['shipments','▣','بارەکان'],['customers','◎','کڕیاران'],['warehouses','▤','کۆگا'],['alerts','!','ئاگاداری']];const labels=new Map([['overview',['⌂','داشبۆرد']],['shipments',['▣','بارەکان']],['alerts',['!','Alerts']],['customers',['◎','کڕیاران']],['pricing',['₿','نرخەکان']],['warehouses',['▤','کۆگاکان']],['finance',['◈','دارایی']],['staff-chat',['✦','چاتی ستاف']],['customer-chat',['◌','چاتی کڕیار']],['requests',['◆','داواکاری']],['activity',['≡','Audit Log']],['settings',['⚙','ڕێکخستن']]]);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function lock(){const o=document.getElementById('gcMobileDrawer')?.classList.contains('open');document.body.classList.toggle('gc-mobile-menu-open',Boolean(o&&mobile()));}function decorate(){const m=document.getElementById('gcMobileMenuBtn');if(m){m.setAttribute('aria-label','کردنەوەی هەموو بەشەکانی ستاف');m.title='هەموو بەشەکان'}const r=document.getElementById('refreshBtn');if(r)r.setAttribute('aria-label','نوێکردنەوەی داتا');const d=document.getElementById('gcMobileCommandDock');if(d)[...d.querySelectorAll('[data-mobile-tab]')].forEach(b=>{const i=primary.find(x=>x[0]===b.dataset.mobileTab)||[b.dataset.mobileTab,'',b.dataset.mobileTab];b.innerHTML='<strong>'+esc(i[1])+'</strong><span>'+esc(i[2])+'</span>';b.setAttribute('aria-label',i[2]);b.title=i[2]});const dr=document.getElementById('gcMobileDrawer');if(dr){dr.querySelectorAll('[data-mobile-tab]').forEach(b=>{const i=labels.get(b.dataset.mobileTab);if(!i)return;b.innerHTML='<strong>'+esc(i[0])+'</strong><span>'+esc(i[1])+'</span>';b.setAttribute('aria-label',i[1]);b.title=i[1]});dr.querySelector('.gc-mobile-user')?.setAttribute('aria-label','حسابی ستاف');}}function sync(){if(document.querySelector('.gc-shell')){decorate();lock()}}const ob=new MutationObserver(sync);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync,{once:true});else sync();ob.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class','aria-expanded']});window.addEventListener('resize',()=>{if(!mobile()){document.body.classList.remove('gc-mobile-menu-open');document.getElementById('gcMobileDrawer')?.classList.remove('open');document.getElementById('gcMobileBackdrop')?.classList.remove('open')}sync()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('gcMobileDrawer')?.classList.remove('open');document.getElementById('gcMobileBackdrop')?.classList.remove('open');document.getElementById('gcMobileMenuBtn')?.setAttribute('aria-expanded','false');lock()}});document.addEventListener('click',e=>{if(!mobile())return;if(e.target.closest('[data-mobile-tab],#gcMobileBackdrop,#gcMobileMenuBtn'))queueMicrotask(lock)})})();